// @TITLE@ EditMode tests: the project policy (ProjectValidator), the kit config against the fleet rules, the house-ad
// host row and the build's versionCode rule. Generated by games/tools/unity/new_game.sh - the game owns it from now on.
using System.Linq;
using CoddyKit.Ads;
using CoddyKit.EditorTools;
using NUnit.Framework;
using @NS@.App;
using @NS@.EditorTools;

namespace @NS@.App.Tests
{
    public class @NS@ProjectTests
    {
        [Test]
        public void ProjectFollowsTheFleetPolicy()
        {
            var problems = ProjectValidator.Problems(@NS@ProjectSetup.Spec);
            Assert.IsEmpty(problems, "run Coddy/@NS@/Apply Project Setup:\n- " + string.Join("\n- ", problems));
        }

        [Test]
        public void OrientationMatchesTheGame()
        {
            Assert.AreEqual(@NS@GameConfig.Landscape, @NS@ProjectSetup.Spec.Landscape);
        }

        [Test]
        public void ReleaseVersionCodeIsBuildTimeSecondsNeverOne()
        {
            const long now = 1_793_200_000;
            Assert.AreEqual(1_793_200_000, @NS@AndroidBuild.ResolveVersionCode("", "internal", now), "missing env = build-time seconds");
            Assert.AreEqual(1_793_200_123, @NS@AndroidBuild.ResolveVersionCode("1793200123", "production", now));
            Assert.AreEqual(0, @NS@AndroidBuild.ResolveVersionCode("1", "internal", now), "a release with vc 1 fails closed");
            Assert.AreEqual(0, @NS@AndroidBuild.ResolveVersionCode("2200000000", "production", now), "above Play's ceiling");
            Assert.AreEqual(5, @NS@AndroidBuild.ResolveVersionCode("5", "dev", now), "dev builds may pin a small code");
        }

        [Test]
        public void AdFreeIsOnlyTheNoadsEntitlement()
        {
            CollectionAssert.AreEqual(new[] { "noads" }, @NS@GameConfig.AdFreeEntitlements);
        }

        [Test]
        public void HouseAdsKnowThisHost()
        {
            Assert.IsTrue(HouseRelated.Related.ContainsKey(@NS@GameConfig.AppId), "add a PENDING row to games/tools/unity/gen_house_related.py and sync");
            Assert.IsFalse(HouseRelated.Related[@NS@GameConfig.AppId].Contains(@NS@GameConfig.AppId), "never self-promotion");
        }

        [Test]
        public void TenLanguagesWithHindi()
        {
            Assert.AreEqual(10, @NS@GameConfig.Languages.Length);
            CollectionAssert.Contains(@NS@GameConfig.Languages, "hi");
        }
    }
}
